# الصورة مضمنة داخل الملف لتسهيل مشاركة ملف Python واحد.
EMBEDDED_IMAGE_JPEG_BASE64 = """"""

def extract_embedded_image(output_path="sex_g6_reference.jpg"):
    """استخراج الصورة المرفقة من داخل ملف المشروع عند الحاجة."""
    from pathlib import Path as _Path
    _Path(output_path).write_bytes(__import__("base64").b64decode(EMBEDDED_IMAGE_JPEG_BASE64))
    return output_path

